public class LifecyclePhasePlannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.List<String> list(String... values) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(values));
    }

    public static void main(String[] args) {
        check("phasesUpTo(package)", "[validate, compile, test, package]",
                String.valueOf(LifecyclePhasePlanner.phasesUpTo("package")));
        check("phasesUpTo(validate)", "[validate]",
                String.valueOf(LifecyclePhasePlanner.phasesUpTo("validate")));
        check("phasesUpTo(deploy) is the whole lifecycle",
                "[validate, compile, test, package, verify, install, deploy]",
                String.valueOf(LifecyclePhasePlanner.phasesUpTo("deploy")));
        check("phasesUpTo of an unknown name", "[]",
                String.valueOf(LifecyclePhasePlanner.phasesUpTo("bogus")));
        check("sortPhases orders, dedupes and filters", "[compile, test, deploy]",
                String.valueOf(LifecyclePhasePlanner.sortPhases(list("deploy", "test", "compile", "test", "bogus"))));
        check("sortPhases of an empty list", "[]",
                String.valueOf(LifecyclePhasePlanner.sortPhases(list())));
        check("comesBefore(compile, install)", true,
                LifecyclePhasePlanner.comesBefore("compile", "install"));
        check("comesBefore(install, compile)", false,
                LifecyclePhasePlanner.comesBefore("install", "compile"));
        check("a phase does not come before itself", false,
                LifecyclePhasePlanner.comesBefore("test", "test"));
        check("comesBefore with an unknown name", false,
                LifecyclePhasePlanner.comesBefore("test", "bogus"));
        finish();
    }
}

