public class LifecyclePhasePlanner {

    private static final java.util.List<String> PHASES = java.util.List.of(
            "validate", "compile", "test", "package", "verify", "install", "deploy");

    public static java.util.List<String> phasesUpTo(String phase) {
        java.util.List<String> result = new java.util.ArrayList<>();
        int index = PHASES.indexOf(phase);
        if (index < 0) {
            return result;
        }
        for (int i = 0; i <= index; i++) {
            result.add(PHASES.get(i));
        }
        return result;
    }

    public static java.util.List<String> sortPhases(java.util.List<String> names) {
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String phase : PHASES) {
            if (names.contains(phase)) {
                result.add(phase);
            }
        }
        return result;
    }

    public static boolean comesBefore(String first, String second) {
        int a = PHASES.indexOf(first);
        int b = PHASES.indexOf(second);
        if (a < 0 || b < 0) {
            return false;
        }
        return a < b;
    }
}
